function indiaToday(){const parts=new Intl.DateTimeFormat("en-CA",{timeZone:"Asia/Kolkata",year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(new Date());const get=(t:string)=>parts.find(p=>p.type===t)?.value??"";return `${get("year")}-${get("month")}-${get("day")}`;}
function daysBetween(a:string,b:string){if(!a||!b)return 9999;return Math.round((Date.parse(a+"T12:00:00Z")-Date.parse(b+"T12:00:00Z"))/86400000);}
function fmtDate(v:string){if(!v)return "—";return new Intl.DateTimeFormat("en-IN",{day:"numeric",month:"short",year:"numeric"}).format(new Date(v+"T12:00:00Z"));}
function done(t:Task){return Boolean(t.complete)||t.status==="Completed"||t.status==="Cancelled";}
function urgency(t:Task,today:string){const d=daysBetween(t.deadline,today);if(done(t))return "DONE";if(d<0)return "DO NOW";if(d===0)return "TODAY";if(d<=3)return "SOON";return "LATER";}
function timeLeft(t:Task,today:string){const d=daysBetween(t.deadline,today);if(!t.deadline)return "No deadline";if(d<0)return `Overdue by ${Math.abs(d)} day${Math.abs(d)===1?"":"s"}`;if(d===0)return "Due today";return `${d} day${d===1?"":"s"} left`;}
function priorityRank(p:string){return priorities.indexOf(p)===-1?9:priorities.indexOf(p);}
function taskSort(a:Task,b:Task,today:string){return priorityRank(a.priority)-priorityRank(b.priority)||daysBetween(a.deadline,today)-daysBetween(b.deadline,today);}
const emptyTask=(today:string):Partial<Task>=>({task:"",category:"Other",subcategory:"",parent_activity:"",context:"",priority:"P2",status:"Not Started",date_created:today,start_date:today,deadline:"",deadline_time:"",deadline_tbd:false,fixed_event:false,event_date:"",event_time:"",estimated_hours:"",actual_hours:"",next_action:"",waiting_for:"",follow_up_date:"",assigned_by:"",team_members:"",deliverable:"",stage:"",venue:"",link:"",notes:""});

function addDays(date:string,count:number){const d=new Date(date+"T12:00:00Z");d.setUTCDate(d.getUTCDate()+count);return d.toISOString().slice(0,10)}
function calendarDate(value:string){if(!value)return "";if(/^\d{4}-\d{2}-\d{2}$/.test(value))return value;const parts=new Intl.DateTimeFormat("en-CA",{timeZone:"Asia/Kolkata",year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(new Date(value));const get=(t:string)=>parts.find(p=>p.type===t)?.value??"";return `${get("year")}-${get("month")}-${get("day")}`;}
function calendarTime(value:string,allDay:boolean){if(allDay)return "All day";return new Intl.DateTimeFormat("en-IN",{timeZone:"Asia/Kolkata",hour:"2-digit",minute:"2-digit",hour12:true}).format(new Date(value));}
function startOfWeek(date:string){const d=new Date(date+"T12:00:00Z");const day=d.getUTCDay();d.setUTCDate(d.getUTCDate()-(day===0?6:day-1));return d.toISOString().slice(0,10)}
function loadGoogleIdentity(){
  if(typeof window==="undefined")return Promise.reject(new Error("Google sign-in is only available in the browser."));
  const w=window as unknown as {google?:unknown;__googleIdentityPromise?:Promise<void>};
  if(w.google)return Promise.resolve();
  if(w.__googleIdentityPromise)return w.__googleIdentityPromise;
  w.__googleIdentityPromise=new Promise<void>((resolve,reject)=>{
    const existing=document.querySelector<HTMLScriptElement>('script[src="https://accounts.google.com/gsi/client"]');
    if(existing){existing.addEventListener("load",()=>resolve(),{once:true});existing.addEventListener("error",()=>reject(new Error("Google sign-in could not load.")),{once:true});return}
    const script=document.createElement("script");script.src="https://accounts.google.com/gsi/client";script.async=true;script.defer=true;script.onload=()=>resolve();script.onerror=()=>reject(new Error("Google sign-in could not load."));document.head.appendChild(script);
  });
  return w.__googleIdentityPromise;
}
function useGoogleCalendar(today:string):CalendarState{
  const [clientIdValue,setClientIdValue]=React.useState(()=>typeof window==="undefined"?"":window.localStorage.getItem("jarvis_google_client_id")??"");
  const [connected,setConnected]=React.useState(false);
  const [account,setAccount]=React.useState("");
  const [events,setEvents]=React.useState<CalendarEvent[]>([]);
  const [calendars,setCalendars]=React.useState(0);
  const [loading,setLoading]=React.useState(false);
  const [error,setError]=React.useState("");
  const [lastSync,setLastSync]=React.useState<number|null>(null);
  const [expiresAt,setExpiresAt]=React.useState<number|null>(null);
  const token=React.useRef("");
  const setClientId=React.useCallback((value:string)=>{const clean=value.trim();setClientIdValue(clean);if(clean)window.localStorage.setItem("jarvis_google_client_id",clean);else window.localStorage.removeItem("jarvis_google_client_id")},[]);
  const sync=React.useCallback(async(accessToken:string)=>{
    setLoading(true);setError("");
    try{
      const headers={Authorization:`Bearer ${accessToken}`};
      const profileResponse=await fetch("https://www.googleapis.com/oauth2/v3/userinfo",{headers});
      if(!profileResponse.ok)throw new Error("Google authorization expired. Connect again.");
      const profile=await profileResponse.json() as {email?:string};
      const email=String(profile.email??"").toLowerCase();
      if(email!==expectedCalendarAccount)throw new Error(`Connected as ${email||"another account"}. Please choose ${expectedCalendarAccount}.`);
      const listResponse=await fetch("https://www.googleapis.com/calendar/v3/users/me/calendarList?maxResults=250",{headers});
      if(!listResponse.ok)throw new Error("Google Calendar access was not granted. Approve read-only Calendar access and try again.");
      const list=await listResponse.json() as {items?:Array<{id:string;summary?:string;selected?:boolean;backgroundColor?:string;accessRole?:string}>};
      const visible=(list.items??[]).filter(c=>c.accessRole!=="none");
      const timeMin=new Date(addDays(today,-35)+"T00:00:00+05:30").toISOString();
      const timeMax=new Date(addDays(today,70)+"T23:59:59+05:30").toISOString();
      const readCalendar=async(calendar:{id:string;summary?:string;backgroundColor?:string})=>{
        const collected:CalendarEvent[]=[];let pageToken="";
        do{
          const params=new URLSearchParams({singleEvents:"true",orderBy:"startTime",showDeleted:"false",maxResults:"2500",timeMin,timeMax,timeZone:"Asia/Kolkata"});
          if(pageToken)params.set("pageToken",pageToken);
          const response=await fetch(`https://www.googleapis.com/calendar/v3/calendars/${encodeURIComponent(calendar.id)}/events?${params}`,{headers});
          if(!response.ok){if(response.status===403)return collected;throw new Error(`Could not read ${calendar.summary??"a calendar"}.`)}
          const data=await response.json() as {items?:Array<{id:string;iCalUID?:string;summary?:string;start?:{date?:string;dateTime?:string};end?:{date?:string;dateTime?:string};location?:string;htmlLink?:string;status?:string}>;nextPageToken?:string};
          for(const item of data.items??[]){
            if(item.status==="cancelled")continue;
            const start=item.start?.dateTime??item.start?.date??"";const end=item.end?.dateTime??item.end?.date??start;if(!start)continue;
            collected.push({id:`${item.iCalUID??item.id}|${start}`,calendarId:calendar.id,calendarName:calendar.summary??"Calendar",title:item.summary??"Busy",start,end,allDay:Boolean(item.start?.date&&!item.start?.dateTime),location:item.location??"",htmlLink:item.htmlLink??"",color:calendar.backgroundColor??"#16d9ff"});
          }
          pageToken=data.nextPageToken??"";
        }while(pageToken);
        return collected;
      };
      const groups=await Promise.all(visible.map(readCalendar));
      const unique=new Map<string,CalendarEvent>();
      for(const event of groups.flat()){const key=`${event.id}|${calendarDate(event.start)}`;if(!unique.has(key))unique.set(key,event)}
      setEvents([...unique.values()].sort((a,b)=>a.start.localeCompare(b.start)));setCalendars(visible.length);setAccount(email);setConnected(true);setLastSync(Date.now());
    }catch(e){setConnected(false);setEvents([]);setCalendars(0);setError(e instanceof Error?e.message:"Google Calendar could not be synchronized.");throw e}
    finally{setLoading(false)}
  },[today]);
  const refresh=React.useCallback(async()=>{if(!token.current){setConnected(false);setError("Connect Google Calendar to load private events.");return}if(expiresAt&&Date.now()>expiresAt-30000){token.current="";setConnected(false);setError("Your secure Google session expired. Connect again to continue live updates.");return}await sync(token.current)},[expiresAt,sync]);
  const connect=React.useCallback(async(clientIdOverride?:string)=>{
    const selectedClientId=(clientIdOverride??clientIdValue).trim();
    if(!selectedClientId){setError("Add your Google OAuth Client ID in Settings first.");return}
    if(clientIdOverride)setClientId(clientIdOverride);
    setLoading(true);setError("");
    try{
      await loadGoogleIdentity();
      const google=(window as unknown as {google:{accounts:{oauth2:{initTokenClient:(config:{client_id:string;scope:string;hint:string;callback:(response:GoogleTokenResponse)=>void;error_callback:(error:unknown)=>void})=>GoogleTokenClient}}}}).google;
      await new Promise<void>((resolve,reject)=>{
        const client=google.accounts.oauth2.initTokenClient({client_id:selectedClientId,scope:"openid email https://www.googleapis.com/auth/calendar.readonly",hint:expectedCalendarAccount,callback:response=>{if(response.error||!response.access_token){reject(new Error(response.error_description??"Google authorization was not completed."));return}token.current=response.access_token;const expiry=Date.now()+Math.max(300,Number(response.expires_in??3600))*1000;setExpiresAt(expiry);void sync(response.access_token).then(resolve).catch(reject)},error_callback:()=>reject(new Error("Google sign-in was closed or blocked."))});
        client.requestAccessToken({prompt:"consent select_account",hint:expectedCalendarAccount});
      });
    }catch(e){setConnected(false);setError(e instanceof Error?e.message:"Google sign-in failed.");setLoading(false)}
  },[clientIdValue,setClientId,sync]);
  const disconnect=React.useCallback(()=>{const accessToken=token.current;token.current="";setConnected(false);setAccount("");setEvents([]);setCalendars(0);setExpiresAt(null);setLastSync(null);setError("");const google=(window as unknown as {google?:{accounts?:{oauth2?:{revoke?:(token:string,done:()=>void)=>void}}}}).google;if(accessToken&&google?.accounts?.oauth2?.revoke)google.accounts.oauth2.revoke(accessToken,()=>{})},[]);
  React.useEffect(()=>{if(!connected)return;const timer=window.setInterval(()=>{void refresh()},60000);return()=>window.clearInterval(timer)},[connected,refresh]);
  return {clientId:clientIdValue,connected,account,events,calendars,loading,error,lastSync,expiresAt,setClientId,connect,disconnect,refresh};
}
function parseVoiceTask(command:string,today:string):Partial<Task>{
  const lower=command.toLowerCase();let category="Other";
  if(/case comp|competition|deck|pitch/.test(lower))category="Case Competition";
  else if(/class|course|assignment|lecture|professor/.test(lower))category="Classes";
  else if(/exam|quiz|test|revision|revise/.test(lower))category="Exams";
  else if(/research|paper|literature|dataset|analysis/.test(lower))category="Research";
  else if(/placement|interview|resume|company|job|application/.test(lower))category="Placements";
  let priority="P2";if(/\bp0\b|critical|urgent|highest priority/.test(lower))priority="P0";else if(/\bp1\b|high priority|important/.test(lower))priority="P1";else if(/\bp3\b|low priority|whenever/.test(lower))priority="P3";
  let deadline="";if(/\btoday\b/.test(lower))deadline=today;else if(/\btomorrow\b/.test(lower))deadline=addDays(today,1);else if(/next week/.test(lower))deadline=addDays(today,7);
  const iso=lower.match(/\b(20\d{2})-(\d{2})-(\d{2})\b/);if(iso)deadline=iso[0];
  const time=lower.match(/\b(?:at|by)\s+(\d{1,2})(?::(\d{2}))?\s*(am|pm)\b/);let deadlineTime="";
  if(time){let h=Number(time[1]);if(time[3]==="pm"&&h<12)h+=12;if(time[3]==="am"&&h===12)h=0;deadlineTime=`${String(h).padStart(2,"0")}:${time[2]??"00"}`}
  const hours=lower.match(/(?:for|estimated?)\s+(\d+(?:\.\d+)?)\s*hours?/);
  let task=command.replace(/^(hey\s+jarvis[, ]*|jarvis[, ]*)?(add|create|make|schedule)\s+(a\s+)?(new\s+)?task\s*(to|for)?\s*/i,"").replace(/^remind me to\s+/i,"");
  task=task.replace(/\s+(today|tomorrow|next week)\b.*$/i,"").replace(/\s+(with|at)\s+(p[0-3]|critical|urgent|high|medium|low)\s+priority.*$/i,"").trim();
  if(!task)task=command.trim();
  return {...emptyTask(today),task,category,priority,deadline,deadline_time:deadlineTime,estimated_hours:hours?.[1]??"",notes:`Voice command: ${command}`};
}

function PriorityBadge({value}:{value:string}){const v=value||"P2";return <Badge className={`priority ${v.toLowerCase()}`}>{v}</Badge>}
function StatusBadge({value}:{value:string}){const v=value||"Not Started";return <Badge variant="outline" className={`status status-${v.toLowerCase().replaceAll(" ","-")}`}>{v}</Badge>}

