  const toggleComplete=async(t:Task,value:boolean)=>{const r=await apiFetch("/api/tasks",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({task_id:t.task_id,complete:value,status:value?"Completed":"Not Started",completion_date:value?today:""})});const d=await r.json();if(r.ok){setTasks(old=>old.map(x=>x.task_id===t.task_id?d.task:x));toast.success(value?"Moved to Archive":"Task reopened");}else toast.error(d.error);};
  const toggleRoutine=async(name:string,value:boolean)=>{setRoutineState(s=>({...s,[name]:value}));setRoutineHistory(old=>{const rest=old.filter(x=>!(x.routine===name&&x.completion_date===today));return [...rest,{routine:name,completion_date:today,complete:value}]});const r=await apiFetch("/api/routines",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({routine:name,date:today,complete:value})});if(!r.ok){toast.error("Routine update could not be saved");void loadRoutines()}};
  React.useEffect(()=>{const ctx=(document as Document & {modelContext?:{registerTool:(t:unknown,o?:unknown)=>unknown}}).modelContext;if(!ctx?.registerTool)return;const ac=new AbortController();void Promise.resolve(ctx.registerTool({name:"add_master_task",title:"Add master task",description:"Create a task in the single MASTER TASKS database.",inputSchema:{type:"object",properties:{task:{type:"string"},category:{type:"string"},priority:{type:"string"},deadline:{type:"string"}},required:["task"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async(input:unknown)=>{const v=input as {task:string;category?:string;priority?:string;deadline?:string};await saveTask({...emptyTask(today),...v});return {created:true,task:v.task};}},{signal:ac.signal})).catch(()=>{});return()=>ac.abort();},[today,saveTask]);
  const active=tasks.filter(t=>!done(t));const overdue=active.filter(t=>t.deadline&&daysBetween(t.deadline,today)<0);const dueToday=active.filter(t=>t.deadline===today);const upcoming=active.filter(t=>{const d=daysBetween(t.deadline,today);return d>0&&d<=7;}).sort((a,b)=>taskSort(a,b,today));const top3=[...active].sort((a,b)=>taskSort(a,b,today)).slice(0,3);const quote=quotes[Math.max(0,Math.floor(Date.parse(today+"T00:00:00Z")/86400000))%quotes.length];const pageTitle=view==="Case Competition"?"Case Comps":view==="master"?"Master Tasks":view.replace(/\b\w/g,c=>c.toUpperCase());
